// ── Shared Patrol Session Map Modal ─────────────────────────────────────────
function PatrolSessionModal({ session, onClose }) {
  const mapRef = useRef(null);
  const mapInstance = useRef(null);

  const fmtTime = t => t ? new Date(t).toLocaleTimeString('en-GB', { hour:'2-digit', minute:'2-digit', timeZone:'Europe/London' }) : '—';
  const fmtDate = t => t ? new Date(t).toLocaleDateString('en-GB', { weekday:'short', day:'2-digit', month:'short', year:'numeric', timeZone:'Europe/London' }) : '—';

  function calcDistance(trail) {
    if (!trail?.length || trail.length < 2) return null;
    let total = 0;
    for (let i = 1; i < trail.length; i++) {
      const R = 6371000;
      const lat1 = trail[i-1].lat * Math.PI/180, lat2 = trail[i].lat * Math.PI/180;
      const dLat = lat2 - lat1, dLng = (trail[i].lng - trail[i-1].lng) * Math.PI/180;
      const a = Math.sin(dLat/2)**2 + Math.cos(lat1)*Math.cos(lat2)*Math.sin(dLng/2)**2;
      total += R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
    }
    return Math.round(total);
  }

  useEffect(() => {
    if (!session || !mapRef.current || mapInstance.current) return;
    function renderMap() {
      if (!window.L || !mapRef.current) return;
      const L = window.L;
      const map = L.map(mapRef.current, { zoomControl: true, attributionControl: false });
      L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', { maxZoom: 19 }).addTo(map);
      const allPoints = [];

      if (session.gps_trail?.length) {
        const trail = session.gps_trail.filter(p => p.lat && p.lng).map(p => [p.lat, p.lng]);
        if (trail.length > 0) {
          L.polyline(trail, { color: '#3b82f6', weight: 3, opacity: 0.9 }).addTo(map);
          L.circleMarker(trail[0], { radius: 8, fillColor: '#22c55e', fillOpacity: 1, color: '#fff', weight: 2 }).addTo(map).bindPopup('Start');
          L.circleMarker(trail[trail.length-1], { radius: 8, fillColor: '#ef4444', fillOpacity: 1, color: '#fff', weight: 2 }).addTo(map).bindPopup('End');
          allPoints.push(...trail);
        }
      }

      if (session.checkpoints_completed?.length) {
        session.checkpoints_completed.forEach((cp, i) => {
          if (!cp.lat || !cp.lng) return;
          const icon = L.divIcon({ html: `<div style="width:22px;height:22px;background:#a78bfa;border:2px solid #fff;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:700;color:#0b1222">${i+1}</div>`, iconSize:[22,22], iconAnchor:[11,11] });
          L.marker([cp.lat, cp.lng], { icon }).addTo(map).bindPopup(cp.name || `Checkpoint ${i+1}`);
          allPoints.push([cp.lat, cp.lng]);
        });
      }

      if (allPoints.length > 0) map.fitBounds(allPoints, { padding: [30, 30] });
      else map.setView([52.48, -1.89], 14);
      mapInstance.current = map;
    }

    if (window.L) { renderMap(); }
    else {
      if (!document.getElementById('leaflet-css')) {
        const link = document.createElement('link'); link.id='leaflet-css'; link.rel='stylesheet';
        link.href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css'; document.head.appendChild(link);
      }
      if (!document.getElementById('leaflet-js')) {
        const script = document.createElement('script'); script.id='leaflet-js';
        script.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';
        script.onload = renderMap; document.head.appendChild(script);
      } else { setTimeout(renderMap, 200); }
    }
    return () => { if (mapInstance.current) { mapInstance.current.remove(); mapInstance.current = null; } };
  }, [session]);

  const duration = session.started_at && session.ended_at
    ? Math.round((new Date(session.ended_at) - new Date(session.started_at)) / 60000) : null;
  const dist = calcDistance(session.gps_trail);
  const checkpoints = session.checkpoints_completed || [];
  const allMedia = [
    ...(session.media || []),
    ...checkpoints.flatMap(cp => [
      ...(cp.media || []),
      ...(cp.photo_url ? [{ url: cp.photo_url, type: 'image/jpeg', name: cp.name || 'photo' }] : []),
    ]),
  ];
  const [lightbox, setLightbox] = useState(null);

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal" style={{maxWidth:'640px',maxHeight:'92vh',overflowY:'auto'}} onClick={e => e.stopPropagation()}>
        <div className="modal-header">
          <div className="modal-title">Patrol — {fmtDate(session.started_at)}</div>
          <button className="modal-close" onClick={onClose}>×</button>
        </div>

        {/* Meta strip */}
        <div style={{display:'flex',gap:'0.75rem',flexWrap:'wrap',marginBottom:'1rem',padding:'0.75rem',background:'var(--surface-2)',borderRadius:'6px'}}>
          {session.officer && <div><div style={{fontSize:'0.6875rem',color:'var(--text-3)',textTransform:'uppercase',marginBottom:'2px'}}>Officer</div><div style={{fontWeight:600,fontSize:'0.875rem'}}>{session.officer.first_name} {session.officer.last_name}</div></div>}
          {session.site && <div><div style={{fontSize:'0.6875rem',color:'var(--text-3)',textTransform:'uppercase',marginBottom:'2px'}}>Site</div><div style={{fontWeight:600,fontSize:'0.875rem'}}>{session.site.name}</div></div>}
          <div><div style={{fontSize:'0.6875rem',color:'var(--text-3)',textTransform:'uppercase',marginBottom:'2px'}}>Time</div><div style={{fontSize:'0.875rem'}}>{fmtTime(session.started_at)}{session.ended_at ? ` → ${fmtTime(session.ended_at)}` : ' (active)'}</div></div>
          {duration != null && <div><div style={{fontSize:'0.6875rem',color:'var(--text-3)',textTransform:'uppercase',marginBottom:'2px'}}>Duration</div><div style={{fontWeight:600,fontSize:'0.875rem'}}>{duration >= 60 ? `${Math.floor(duration/60)}h ${duration%60}m` : `${duration}m`}</div></div>}
        </div>

        {/* Stats */}
        <div style={{display:'flex',gap:'0.75rem',marginBottom:'1rem'}}>
          <div style={{flex:1,padding:'0.625rem',background:'var(--surface-2)',borderRadius:'6px',textAlign:'center'}}>
            <div style={{fontSize:'1.25rem',fontWeight:700}}>{checkpoints.length}</div>
            <div style={{fontSize:'0.6875rem',color:'var(--text-3)',textTransform:'uppercase'}}>Checkpoints</div>
          </div>
          {dist != null && <div style={{flex:1,padding:'0.625rem',background:'var(--surface-2)',borderRadius:'6px',textAlign:'center'}}>
            <div style={{fontSize:'1.25rem',fontWeight:700}}>{dist >= 1000 ? `${(dist/1000).toFixed(1)}km` : `${dist}m`}</div>
            <div style={{fontSize:'0.6875rem',color:'var(--text-3)',textTransform:'uppercase'}}>Distance</div>
          </div>}
          {session.gps_trail?.length > 0 && <div style={{flex:1,padding:'0.625rem',background:'var(--surface-2)',borderRadius:'6px',textAlign:'center'}}>
            <div style={{fontSize:'1.25rem',fontWeight:700}}>{session.gps_trail.length}</div>
            <div style={{fontSize:'0.6875rem',color:'var(--text-3)',textTransform:'uppercase'}}>GPS Points</div>
          </div>}
        </div>

        {/* Map */}
        <div ref={mapRef} style={{width:'100%',height:'320px',borderRadius:'8px',border:'1px solid var(--border)',marginBottom:'1rem'}} />

        {/* Checkpoints */}
        {checkpoints.length > 0 && (
          <div style={{marginBottom:'1rem'}}>
            <div style={{fontSize:'0.75rem',fontWeight:700,color:'var(--text-3)',textTransform:'uppercase',letterSpacing:'0.08em',marginBottom:'0.5rem'}}>Checkpoints</div>
            <div style={{display:'flex',flexDirection:'column',gap:'0.375rem'}}>
              {checkpoints.map((cp, i) => (
                <div key={i} style={{display:'flex',alignItems:'center',gap:'0.625rem',padding:'0.5rem 0.625rem',background:'var(--surface-2)',borderRadius:'6px'}}>
                  <div style={{width:22,height:22,borderRadius:'50%',background:'#a78bfa',display:'flex',alignItems:'center',justifyContent:'center',fontSize:'10px',fontWeight:700,color:'#0b1222',flexShrink:0}}>{i+1}</div>
                  <div style={{flex:1,fontSize:'0.8125rem',fontWeight:500}}>{typeof cp === 'object' ? cp.name || `Checkpoint ${i+1}` : cp}</div>
                  {typeof cp === 'object' && cp.timestamp && <div style={{fontSize:'0.75rem',color:'var(--text-3)',flexShrink:0}}>{fmtTime(cp.timestamp)}</div>}
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Photos */}
        {allMedia.length > 0 && (
          <div style={{marginBottom:'1rem'}}>
            <div style={{fontSize:'0.75rem',fontWeight:700,color:'var(--text-3)',textTransform:'uppercase',letterSpacing:'0.08em',marginBottom:'0.5rem'}}>Photos ({allMedia.length})</div>
            <div style={{display:'flex',gap:'8px',flexWrap:'wrap'}}>
              {allMedia.map((m, i) => (
                <div key={i} onClick={() => m.type?.startsWith('image') && setLightbox(m.url)}
                  style={{width:80,height:80,borderRadius:'8px',overflow:'hidden',border:'1px solid var(--border)',cursor:'zoom-in',flexShrink:0}}>
                  <img src={m.url} style={{width:'100%',height:'100%',objectFit:'cover'}} alt={m.name||'photo'} />
                </div>
              ))}
            </div>
          </div>
        )}

        <div className="modal-footer">
          <button className="btn btn-secondary" onClick={onClose}>Close</button>
        </div>
      </div>

      {lightbox && (
        <div onClick={() => setLightbox(null)} style={{position:'fixed',inset:0,background:'rgba(0,0,0,0.92)',zIndex:10000,display:'flex',alignItems:'center',justifyContent:'center',padding:'1rem'}}>
          <img src={lightbox} style={{maxWidth:'100%',maxHeight:'90vh',borderRadius:'8px',objectFit:'contain'}} />
          <button onClick={() => setLightbox(null)} style={{position:'absolute',top:'1rem',right:'1rem',background:'rgba(255,255,255,0.15)',border:'none',color:'#fff',width:36,height:36,borderRadius:'50%',fontSize:'1.25rem',cursor:'pointer',display:'flex',alignItems:'center',justifyContent:'center'}}>×</button>
        </div>
      )}
    </div>
  );
}

// ── Manager Patrol History Screen ────────────────────────────────────────────
function PatrolHistoryScreen({ user }) {
  const [sessions, setSessions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selected, setSelected] = useState(null);
  const [loadingSession, setLoadingSession] = useState(false);
  const [siteFilter, setSiteFilter] = useState('');
  const [sites, setSites] = useState([]);

  useEffect(() => {
    async function load() {
      try {
        const [sessRes, sitesRes] = await Promise.all([
          api.patrols.listSessions({ limit: 100 }),
          api.sites.list(),
        ]);
        setSessions(sessRes.data || []);
        setSites(sitesRes.data || []);
      } catch (err) { console.error(err); }
      finally { setLoading(false); }
    }
    load();
  }, []);

  async function openSession(s) {
    if (s.gps_trail) { setSelected(s); return; }
    setLoadingSession(true);
    try {
      const res = await api.patrols.getSession(s.id);
      setSelected(res.data);
    } catch (err) { alert('Failed to load patrol: ' + err.message); }
    finally { setLoadingSession(false); }
  }

  const filtered = siteFilter ? sessions.filter(s => s.site_id === siteFilter) : sessions;

  const fmtDate = t => t ? new Date(t).toLocaleDateString('en-GB', { day:'2-digit', month:'short', year:'numeric', timeZone:'Europe/London' }) : '—';
  const fmtTime = t => t ? new Date(t).toLocaleTimeString('en-GB', { hour:'2-digit', minute:'2-digit', timeZone:'Europe/London' }) : '—';
  const duration = s => s.started_at && s.ended_at ? Math.round((new Date(s.ended_at) - new Date(s.started_at)) / 60000) : null;
  const fmtDur = d => d == null ? '—' : d >= 60 ? `${Math.floor(d/60)}h ${d%60}m` : `${d}m`;

  return (
    <div style={{padding:'1.5rem'}}>
      <div style={{display:'flex',alignItems:'center',justifyContent:'space-between',marginBottom:'1.25rem',flexWrap:'wrap',gap:'0.75rem'}}>
        <div>
          <h2 style={{fontSize:'1.125rem',fontWeight:700,margin:0}}>Patrol History</h2>
          <p style={{fontSize:'0.8125rem',color:'var(--text-2)',margin:'0.25rem 0 0'}}>All completed patrols — click to view route map</p>
        </div>
        <select value={siteFilter} onChange={e => setSiteFilter(e.target.value)}
          style={{padding:'0.5rem 0.75rem',background:'var(--surface-2)',border:'1px solid var(--border)',borderRadius:'6px',color:'var(--text)',fontSize:'0.875rem'}}>
          <option value="">All Sites</option>
          {sites.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
        </select>
      </div>

      {loading ? (
        <div style={{display:'flex',justifyContent:'center',padding:'3rem'}}><div className="spinner" /></div>
      ) : filtered.length === 0 ? (
        <div style={{textAlign:'center',padding:'3rem',color:'var(--text-3)'}}>No patrols found</div>
      ) : (
        <div style={{overflowX:'auto'}}>
          <table style={{width:'100%',borderCollapse:'collapse'}}>
            <thead>
              <tr style={{borderBottom:'1px solid var(--border)'}}>
                {['Date','Officer','Site','Start','End','Duration','Checkpoints','GPS Points',''].map(h => (
                  <th key={h} style={{padding:'0.625rem 0.75rem',textAlign:'left',fontSize:'0.75rem',fontWeight:600,color:'var(--text-2)',whiteSpace:'nowrap'}}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {filtered.map(s => (
                <tr key={s.id} onClick={() => openSession(s)}
                  style={{borderBottom:'1px solid var(--border)',cursor:'pointer'}}
                  onMouseEnter={e => e.currentTarget.style.background='var(--surface-2)'}
                  onMouseLeave={e => e.currentTarget.style.background=''}>
                  <td style={{padding:'0.625rem 0.75rem',fontSize:'0.8125rem',whiteSpace:'nowrap'}}>{fmtDate(s.started_at)}</td>
                  <td style={{padding:'0.625rem 0.75rem',fontSize:'0.8125rem'}}>{s.officer ? `${s.officer.first_name} ${s.officer.last_name}` : '—'}</td>
                  <td style={{padding:'0.625rem 0.75rem',fontSize:'0.8125rem'}}>{s.site?.name || '—'}</td>
                  <td style={{padding:'0.625rem 0.75rem',fontSize:'0.8125rem',whiteSpace:'nowrap'}}>{fmtTime(s.started_at)}</td>
                  <td style={{padding:'0.625rem 0.75rem',fontSize:'0.8125rem',whiteSpace:'nowrap'}}>{fmtTime(s.ended_at)}</td>
                  <td style={{padding:'0.625rem 0.75rem',fontSize:'0.8125rem',fontWeight:600}}>{fmtDur(duration(s))}</td>
                  <td style={{padding:'0.625rem 0.75rem',fontSize:'0.8125rem',textAlign:'center'}}>{(s.checkpoints_completed?.length) || 0}</td>
                  <td style={{padding:'0.625rem 0.75rem',fontSize:'0.8125rem',textAlign:'center'}}>{s.gps_trail?.length || 0}</td>
                  <td style={{padding:'0.625rem 0.75rem',fontSize:'0.75rem',color:'var(--blue)',whiteSpace:'nowrap'}}>View map →</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {loadingSession && (
        <div style={{position:'fixed',inset:0,background:'rgba(0,0,0,0.5)',zIndex:9999,display:'flex',alignItems:'center',justifyContent:'center'}}>
          <div className="spinner" />
        </div>
      )}

      {selected && <PatrolSessionModal session={selected} onClose={() => setSelected(null)} />}
    </div>
  );
}

// ── Site Assignment Instructions Editor ───────────────────────────────────────
function SiteAIEditor({ siteId, siteName }) {
  const [ai, setAI] = useState(null);
  const [sections, setSections] = useState([]);
  const [title, setTitle] = useState('Assignment Instructions');
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [publishing, setPublishing] = useState(false);
  const [success, setSuccess] = useState(null);
  const [error, setError] = useState(null);
  const [revisions, setRevisions] = useState([]);
  const [showRevisions, setShowRevisions] = useState(false);
  const [viewingRev, setViewingRev] = useState(null);
  const [declarations, setDeclarations] = useState(null);
  const [showDeclarations, setShowDeclarations] = useState(false);
  const [pdfLoading, setPdfLoading] = useState(false);

  useEffect(() => {
    setLoading(true);
    Promise.all([
      api.siteAI.get(siteId),
      api.siteAI.revisions(siteId),
    ]).then(([aiRes, revRes]) => {
      const d = aiRes.data;
      if (d) {
        setAI(d);
        setTitle(d.title || 'Assignment Instructions');
        setSections(d.sections || []);
      }
      setRevisions(revRes.data || []);
    }).catch(e => setError(e.message))
      .finally(() => setLoading(false));
  }, [siteId]);

  function addSection() {
    setSections(s => [...s, { title: '', content: '' }]);
  }
  function updateSection(i, field, val) {
    setSections(s => s.map((sec, j) => j === i ? { ...sec, [field]: val } : sec));
  }
  function removeSection(i) {
    setSections(s => s.filter((_, j) => j !== i));
  }
  function moveSection(i, dir) {
    setSections(s => {
      const arr = [...s];
      const target = i + dir;
      if (target < 0 || target >= arr.length) return arr;
      [arr[i], arr[target]] = [arr[target], arr[i]];
      return arr;
    });
  }

  async function save() {
    try {
      setSaving(true); setError(null);
      const res = await api.siteAI.save(siteId, { title, sections });
      setAI(res.data);
      setSuccess('Draft saved');
      setTimeout(() => setSuccess(null), 2000);
    } catch (e) { setError(e.message); }
    finally { setSaving(false); }
  }

  async function publish() {
    if (!confirm(`Publish Revision ${(ai?.revision || 0) + 1}? Officers will need to re-declare.`)) return;
    try {
      setPublishing(true); setError(null);
      // Save first to ensure latest content is persisted
      await api.siteAI.save(siteId, { title, sections });
      const res = await api.siteAI.publish(siteId);
      setAI(res.data);
      setSuccess(`Published as Revision ${res.revision}`);
      // Refresh revisions
      const revRes = await api.siteAI.revisions(siteId);
      setRevisions(revRes.data || []);
      setTimeout(() => setSuccess(null), 3000);
    } catch (e) { setError(e.message); }
    finally { setPublishing(false); }
  }

  async function viewRevision(rev) {
    try {
      const res = await api.siteAI.revision(siteId, rev);
      setViewingRev(res.data);
    } catch (e) { setError(e.message); }
  }

  async function loadDeclarations() {
    setShowDeclarations(!showDeclarations);
    if (!showDeclarations) {
      try {
        const res = await api.siteAI.declarations(siteId);
        setDeclarations(res);
      } catch (e) { setError(e.message); }
    }
  }

  async function downloadPdf(revision) {
    try {
      setPdfLoading(true);
      const res = await api.siteAI.pdf(siteId, revision);
      const blob = new Blob([Uint8Array.from(atob(res.pdf), c => c.charCodeAt(0))], { type: 'application/pdf' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a'); a.href = url; a.download = res.filename; a.click();
      URL.revokeObjectURL(url);
    } catch (e) { setError(e.message); }
    finally { setPdfLoading(false); }
  }

  if (loading) return <div style={{display:'flex',justifyContent:'center',padding:'3rem'}}><div className="spinner" /></div>;

  return (
    <div>
      {/* Header bar */}
      <div style={{display:'flex',alignItems:'center',justifyContent:'space-between',marginBottom:'1rem',flexWrap:'wrap',gap:'0.5rem'}}>
        <div style={{display:'flex',alignItems:'center',gap:'0.75rem'}}>
          <div style={{fontWeight:700,fontSize:'1rem'}}>Assignment Instructions</div>
          {ai?.revision > 0 && (
            <span className="badge badge-info" style={{fontSize:'0.6875rem'}}>Rev {ai.revision} — {ai.status === 'published' ? 'Published' : 'Draft'}</span>
          )}
          {ai?.revision === 0 && <span className="badge badge-neutral" style={{fontSize:'0.6875rem'}}>New — Unpublished</span>}
          {ai?.revision > 0 && ai?.client_approved && (
            <span style={{fontSize:'0.6875rem',padding:'2px 8px',borderRadius:'999px',fontWeight:600,background:'rgba(16,185,129,0.1)',color:'#059669',border:'1px solid rgba(16,185,129,0.3)'}}>
              Client: {ai.client_approved_by} — {new Date(ai.client_approved_at).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})}
            </span>
          )}
          {ai?.revision > 0 && ai?.status === 'published' && !ai?.client_approved && (
            <span style={{fontSize:'0.6875rem',padding:'2px 8px',borderRadius:'999px',fontWeight:600,background:'rgba(245,158,11,0.1)',color:'#d97706',border:'1px solid rgba(245,158,11,0.3)'}}>
              Client approval pending
            </span>
          )}
        </div>
        <div style={{display:'flex',gap:'0.5rem',alignItems:'center'}}>
          {ai?.revision > 0 && (
            <>
              <button className="btn btn-ghost btn-sm" onClick={loadDeclarations}>
                {showDeclarations ? 'Hide' : 'Declarations'}
              </button>
              <button className="btn btn-ghost btn-sm" onClick={() => setShowRevisions(!showRevisions)}>
                {showRevisions ? 'Hide History' : `History (${revisions.length})`}
              </button>
              <button className="btn btn-ghost btn-sm" onClick={() => downloadPdf(ai.revision)} disabled={pdfLoading}>
                {pdfLoading ? 'Generating…' : 'Download PDF'}
              </button>
            </>
          )}
          <button className="btn btn-ghost btn-sm" onClick={addSection}>+ Section</button>
          <button className="btn btn-primary btn-sm" onClick={save} disabled={saving}>{saving ? 'Saving…' : 'Save Draft'}</button>
          <button className="btn btn-sm" style={{background:'#16a34a',color:'#fff',border:'none',fontWeight:600}} onClick={publish} disabled={publishing}>
            {publishing ? 'Publishing…' : `Publish Rev ${(ai?.revision || 0) + 1}`}
          </button>
        </div>
      </div>

      {success && <div className="alert alert-success" style={{marginBottom:'1rem'}}>{success}</div>}
      {error && <div className="alert alert-danger" style={{marginBottom:'1rem'}}>{error}</div>}

      {/* Declarations panel */}
      {showDeclarations && declarations && (
        <div className="card" style={{marginBottom:'1rem',padding:'1rem'}}>
          <div style={{fontWeight:700,fontSize:'0.875rem',marginBottom:'0.75rem'}}>
            Declarations — Revision {declarations.revision}
          </div>
          {(declarations.data || []).length === 0 ? (
            <div style={{fontSize:'0.8125rem',color:'var(--text-3)'}}>No officers assigned to this site.</div>
          ) : (
            <table style={{width:'100%',borderCollapse:'collapse',fontSize:'0.8125rem'}}>
              <thead>
                <tr style={{borderBottom:'1px solid var(--border)'}}>
                  <th style={{textAlign:'left',padding:'0.375rem 0.5rem',fontWeight:600,color:'var(--text-3)',fontSize:'0.6875rem'}}>Officer</th>
                  <th style={{textAlign:'center',padding:'0.375rem 0.5rem',fontWeight:600,color:'var(--text-3)',fontSize:'0.6875rem'}}>Status</th>
                  <th style={{textAlign:'right',padding:'0.375rem 0.5rem',fontWeight:600,color:'var(--text-3)',fontSize:'0.6875rem'}}>Date</th>
                </tr>
              </thead>
              <tbody>
                {(declarations.data || []).map(o => (
                  <tr key={o.id} style={{borderBottom:'1px solid var(--border)'}}>
                    <td style={{padding:'0.375rem 0.5rem',fontWeight:500}}>{o.first_name} {o.last_name}</td>
                    <td style={{padding:'0.375rem 0.5rem',textAlign:'center'}}>
                      {o.declared
                        ? <span style={{color:'#16a34a',fontWeight:600}}>✓ Declared</span>
                        : <span style={{color:'#ef4444',fontWeight:600}}>Outstanding</span>}
                    </td>
                    <td style={{padding:'0.375rem 0.5rem',textAlign:'right',color:'var(--text-3)',fontSize:'0.75rem'}}>
                      {o.declared_at ? new Date(o.declared_at).toLocaleDateString('en-GB', { day:'numeric', month:'short', year:'numeric' }) : '—'}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}

      {/* Revision history panel */}
      {showRevisions && (
        <div className="card" style={{marginBottom:'1rem',padding:'1rem'}}>
          <div style={{fontWeight:700,fontSize:'0.875rem',marginBottom:'0.75rem'}}>Revision History</div>
          {revisions.length === 0 ? (
            <div style={{fontSize:'0.8125rem',color:'var(--text-3)'}}>No published revisions yet.</div>
          ) : (
            <div style={{display:'flex',flexDirection:'column',gap:'0.375rem'}}>
              {revisions.map(r => (
                <div key={r.id} style={{display:'flex',justifyContent:'space-between',alignItems:'center',padding:'0.5rem 0.75rem',background:'var(--surface)',border:'1px solid var(--border)',borderRadius:'6px',fontSize:'0.8125rem'}}>
                  <div>
                    <span style={{fontWeight:700,color:'var(--blue)',marginRight:'0.5rem'}}>Rev {r.revision}</span>
                    <span>{r.title}</span>
                    <span style={{color:'var(--text-3)',fontSize:'0.6875rem',marginLeft:'0.5rem'}}>
                      by {r.publisher?.first_name} {r.publisher?.last_name}
                    </span>
                  </div>
                  <div style={{display:'flex',gap:'0.5rem',alignItems:'center'}}>
                    <span style={{fontSize:'0.6875rem',color:'var(--text-3)'}}>
                      {new Date(r.published_at).toLocaleDateString('en-GB', { day:'numeric', month:'short', year:'numeric' })}
                    </span>
                    <button className="btn btn-ghost btn-sm" style={{fontSize:'0.6875rem'}} onClick={() => viewRevision(r.revision)}>View</button>
                    <button className="btn btn-ghost btn-sm" style={{fontSize:'0.6875rem'}} onClick={() => downloadPdf(r.revision)}>PDF</button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* Viewing old revision */}
      {viewingRev && (
        <div className="card" style={{marginBottom:'1rem',padding:'1rem',border:'2px solid var(--blue)'}}>
          <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:'0.75rem'}}>
            <div style={{fontWeight:700,fontSize:'0.875rem',color:'var(--blue)'}}>
              Viewing Revision {viewingRev.revision} — {viewingRev.title}
            </div>
            <button className="btn btn-ghost btn-sm" onClick={() => setViewingRev(null)}>Close</button>
          </div>
          <div style={{fontSize:'0.75rem',color:'var(--text-3)',marginBottom:'1rem'}}>
            Published {new Date(viewingRev.published_at).toLocaleDateString('en-GB', { day:'numeric', month:'long', year:'numeric' })}
          </div>
          {(viewingRev.sections || []).map((sec, i) => (
            <div key={i} style={{marginBottom:'1rem'}}>
              <div style={{fontWeight:700,fontSize:'0.875rem',color:'var(--text)',marginBottom:'0.25rem'}}>{i + 1}. {sec.title}</div>
              <div style={{fontSize:'0.8125rem',color:'var(--text-2)',whiteSpace:'pre-line',lineHeight:1.6}}>{sec.content}</div>
            </div>
          ))}
        </div>
      )}

      {/* Title */}
      <div className="card" style={{marginBottom:'0.75rem',padding:'0.875rem 1rem'}}>
        <label style={{fontSize:'0.6875rem',fontWeight:700,color:'var(--text-3)',textTransform:'uppercase',letterSpacing:'0.05em',marginBottom:'0.25rem',display:'block'}}>Document Title</label>
        <input className="input" value={title} onChange={e => setTitle(e.target.value)} placeholder="Assignment Instructions" style={{fontWeight:600,fontSize:'1rem'}} />
      </div>

      {/* Sections editor */}
      {sections.length === 0 ? (
        <div className="empty-state">
          <p>No sections yet. Add the first section to start building the Assignment Instructions for {siteName}.</p>
          <button className="btn btn-primary" style={{marginTop:'1rem'}} onClick={addSection}>Add First Section</button>
        </div>
      ) : (
        <div style={{display:'flex',flexDirection:'column',gap:'0.75rem'}}>
          {sections.map((sec, i) => (
            <div key={i} className="card" style={{padding:'1rem'}}>
              <div style={{display:'flex',alignItems:'center',justifyContent:'space-between',marginBottom:'0.5rem'}}>
                <div style={{display:'flex',alignItems:'center',gap:'0.5rem'}}>
                  <span style={{fontSize:'0.75rem',fontWeight:800,color:'var(--blue)',minWidth:'1.5rem'}}>{i + 1}.</span>
                  <input className="input" value={sec.title} onChange={e => updateSection(i, 'title', e.target.value)}
                    placeholder="Section title (e.g. Site Threats, Emergency Procedures)" style={{fontWeight:600,flex:1}} />
                </div>
                <div style={{display:'flex',gap:'0.25rem',marginLeft:'0.5rem'}}>
                  <button className="btn btn-ghost btn-sm" style={{fontSize:'0.6875rem',padding:'0.25rem 0.5rem'}} onClick={() => moveSection(i, -1)} disabled={i === 0}>↑</button>
                  <button className="btn btn-ghost btn-sm" style={{fontSize:'0.6875rem',padding:'0.25rem 0.5rem'}} onClick={() => moveSection(i, 1)} disabled={i === sections.length - 1}>↓</button>
                  <button className="btn btn-ghost btn-sm" style={{color:'var(--danger)',fontSize:'0.6875rem'}} onClick={() => removeSection(i)}>Remove</button>
                </div>
              </div>
              <textarea className="input" rows={8} value={sec.content} onChange={e => updateSection(i, 'content', e.target.value)}
                placeholder="Section content — plain text. Use line breaks for structure." style={{fontSize:'0.8125rem',lineHeight:1.6}} />
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

